import test from 'node:test';import assert from 'node:assert/strict';
import * as T from '../../vendor/three.module.js';
import {createRanchPhysics} from '../ranch-adapter.mjs';
function fixture(withFixture=false){const root=new T.Group(),tile=new T.Group();root.add(tile);const ground=new T.Mesh(new T.PlaneGeometry(10,10));ground.rotation.x=-Math.PI/2;tile.add(ground);const lifeRoot=new T.Group();lifeRoot.scale.setScalar(.1);root.add(lifeRoot);const body=new T.Group();body.position.set(0,0,0);lifeRoot.add(body);let pen=null;if(withFixture){pen=new T.Group();pen.position.x=2;lifeRoot.add(pen);pen.add(body);const shelter=new T.Mesh(new T.BoxGeometry(1,1,1));shelter.position.set(3,.5,0);pen.add(shelter);body.add(new T.Mesh(new T.SphereGeometry(.3,8,4)));}let live=true,state={stock:7,cargo:3,owned:false},allow=false,releases=0,target=null,attempts=0;const entities=()=>live?[{bodyId:'slot',storyId:'human-17',body,position:body.getWorldPosition(new T.Vector3()).multiplyScalar(10).toArray(),radius:.3,centerOffset:[0,.3,0],tileId:'a'}]:[];const adapter=createRanchPhysics({root,assembly:{plans:[{id:'a',center:{x:0,z:0}}]},tileObjects:[{id:'a',object:tile,collisionMeshes:[ground]}],radiusMetres:50,entities,fixtures:()=>pen?[{tileId:'a',object:pen,excludeBodies:true}]:[],behavior:{recoveryTarget(){attempts++;return target;},acquire(){state.owned=true;},release(){releases++;if(allow){state.owned=false;return true;}return false;}},snapshotBehavior:()=>structuredClone(state),restoreBehavior:s=>{state=s;}});return {adapter,body,tile,pen,get state(){return state;},set allow(v){allow=v;},get releases(){return releases;},get attempts(){return attempts;},set target(v){target=v;},remove(){live=false;}};}
const run=(a,seconds)=>{for(let i=0;i<seconds*120;i++)a.update(1/120);};
test('adapter acquires pose, moves real floor and keeps explicit foot offset',()=>{const f=fixture();f.adapter.begin('a');f.adapter.move({position:[0,1,0]},.2);run(f.adapter,2);assert.ok(f.body.getWorldPosition(new T.Vector3()).y>.099);assert.ok(f.body.getWorldPosition(new T.Vector3()).y<.102);assert.equal(f.state.owned,true);assert.equal(f.state.cargo+f.state.stock,10);});
test('cancel atomically restores behavior, collider frame, body pose and physical state',()=>{const f=fixture(),before=f.adapter.snapshot();f.adapter.begin('a',{response:'carry-on'});f.adapter.move({position:[2,3,1]},.2);run(f.adapter,.3);f.adapter.cancel();assert.deepEqual(f.adapter.snapshot(),before);assert.equal(f.body.position.y,0);assert.equal(f.tile.position.y,0);});
test('unsafe recovery retains ownership, then releases only when behavior accepts',()=>{const f=fixture();f.adapter.begin('a');f.adapter.end();run(f.adapter,.8);assert.ok(f.releases>0);assert.deepEqual(f.adapter.owned,['slot']);f.allow=true;run(f.adapter,.1);assert.deepEqual(f.adapter.owned,[]);assert.equal(f.state.owned,false);});
test('removed or retired organism never leaves a ghost physical body',()=>{const f=fixture();f.adapter.begin('a');f.remove();f.adapter.update(1/120);assert.equal(f.adapter.world.bodies.size,0);assert.deepEqual(f.adapter.owned,[]);});

test('nested metre-scale fixture follows tile, excludes actor collider and cancels exactly',()=>{const f=fixture(true);assert.equal(f.adapter.world.tiles.get('a').triangles.length,14);f.adapter.begin('a');f.adapter.move({position:[0,1,0]},.2);run(f.adapter,2);assert.ok(Math.abs(f.pen.getWorldPosition(new T.Vector3()).y-.1)<1e-8);assert.ok(Math.abs(f.body.getWorldPosition(new T.Vector3()).y-.1)<.002);f.adapter.cancel();assert.equal(f.pen.position.y,0);assert.equal(f.body.position.y,0);});
test('settling on a displaced tile cannot release to obsolete navigation routes',()=>{const f=fixture();f.allow=true;f.adapter.begin('a');f.adapter.move({position:[0,.2,0]},.1);run(f.adapter,1);f.adapter.end();run(f.adapter,1);assert.equal(f.releases,0);assert.deepEqual(f.adapter.owned,['slot']);f.adapter.returnTile('a');run(f.adapter,2);assert.ok(f.releases>0);assert.deepEqual(f.adapter.owned,[]);});

test('recovery steering never starts on a displaced disconnected tile',()=>{const f=fixture();f.target={position:[1,0,0],maxDistance:2};f.adapter.begin('a');f.adapter.move({position:[0,.2,0]},.1);run(f.adapter,1);f.adapter.end();run(f.adapter,1);assert.equal(f.attempts,0);assert.equal(f.adapter.world.bodies.get('slot').recovery,undefined);f.adapter.returnTile('a');run(f.adapter,1);assert.equal(f.attempts,1);});
test('manipulation begins with ordered per-body behavior events',()=>{const f=fixture();f.adapter.begin('a',{response:'panic'});const events=f.adapter.drainEvents();assert.ok(events.some(e=>e.type==='manipulation'&&e.bodyId==='slot'&&e.phase==='begin'&&e.response==='panic'));assert.ok(events.every((e,i)=>!i||e.sequence>events[i-1].sequence));});

test('cancel preserves exact Euler representation used by behavioral heading',()=>{const f=fixture(true);f.body.rotation.y=-4.4;const before=f.body.rotation.toArray();f.adapter.begin('a');f.adapter.move({position:[0,1,0],rotation:[0,0,.05,Math.sqrt(1-.05*.05)]},.2);run(f.adapter,.3);f.adapter.cancel();assert.deepEqual(f.body.rotation.toArray(),before);});
test('drop and re-grab retain one transaction and Cancel restores its original ledger',()=>{const f=fixture(),before=f.adapter.snapshot();f.adapter.begin('a');f.adapter.move({position:[0,2,0]},.2);run(f.adapter,.2);f.adapter.drop();assert.equal(f.adapter.world.tiles.get('a').dynamic,true);run(f.adapter,.2);f.adapter.grab('a');assert.equal(f.adapter.held,'a');assert.equal(f.adapter.world.tiles.get('a').dynamic,false);f.adapter.move({position:[1,1,0]},.2);run(f.adapter,.2);f.adapter.cancel();assert.deepEqual(f.adapter.snapshot(),before);f.adapter.dispose();});
